using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TravelWorldTests
{
 static WorldSession New()=>new(TravelWorld.Create());
 static void Go(WorldSession s,string node){var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:trip/"+s.DiagnosticSnapshot().Requests.Length,node);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);s.AdvanceTo(s.Seconds+1);}
 static void Arrive(WorldSession s){s.AdvanceTo(s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);}
 [Fact] public void ArrivalBecomesNextOriginAndReturnNeedsNoRemoteLord(){var s=New();Go(s,"sakai");Arrive(s);var at=s.Seconds;Go(s,"sumoto");Assert.Equal("sakai",s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[0].From);Assert.Equal(at+1,s.DiagnosticSnapshot().Tasks.Last().StartedAt);Arrive(s);Go(s,"castle");Arrive(s);Assert.Equal(ContractFixture.Castle,s.GetActorView(ContractFixture.Officer).Location.Site);Assert.Equal(3,s.DiagnosticSnapshot().Branches!.Journeys.Length);Assert.All(s.DiagnosticSnapshot().Tasks,t=>Assert.Equal(t.Issuer,t.Executor));}
 [Fact] public void PendingAndSamePlaceAndTamperedOrdersAreRejected(){var s=New();Assert.Throws<InvalidDataException>(()=>TravelWorld.Move(s.DiagnosticSnapshot(),"request:same","castle"));var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:bad","sakai");Assert.NotEqual(ResultCode.Accepted,s.Submit(i with{Actor=ContractFixture.Lord},s.Revision).Code);Go(s,"sakai");Assert.Throws<InvalidDataException>(()=>TravelWorld.Move(s.DiagnosticSnapshot(),"request:busy","sumoto"));}
 [Fact] public void PortWaitDepartureAndMovementShareOneClock(){var s=New();Go(s,"sumoto");var l=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs.First(l=>NationalRoutes.Sea(l.Edge));var depart=TravelWorld.Departure(s.DiagnosticSnapshot(),l.Edge,l.StartAt);Assert.True(depart>=l.StartAt+300);Assert.Equal(0,depart%3600);s.AdvanceTo(l.StartAt);var p=s.GetBranchView(ContractFixture.Officer).Position;Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);s.AdvanceTo(depart-1);Assert.Equal(p,s.GetBranchView(ContractFixture.Officer).Position);Assert.Equal(0,s.GetBranchView(ContractFixture.Officer).StepDistanceMm);s.AdvanceTo(depart);Assert.True(s.GetBranchView(ContractFixture.Officer).Walking);s.AdvanceTo(depart+1);Assert.NotEqual(p,s.GetBranchView(ContractFixture.Officer).Position);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)] public void RestoreAtArrivalPortAndSeaContinuesExactly(int phase){var s=New();Go(s,"sakai");Arrive(s);if(phase>0){Go(s,"sumoto");var l=s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs.First(l=>NationalRoutes.Sea(l.Edge));s.AdvanceTo(phase==1?l.StartAt:TravelWorld.Departure(s.DiagnosticSnapshot(),l.Edge,l.StartAt)+100);}var root=Path.Combine(Path.GetTempPath(),"travel-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,TravelWorld.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));host.Current.SetPaused(false);if(phase==0){Go(s,"sumoto");Go(host.Current,"sumoto");}Arrive(s);Arrive(host.Current);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Branches),ContractJson.Write(host.Current.DiagnosticSnapshot().Branches));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));}
 [Fact] public void OldNationalSavesNeedExplicitMigration(){var s=new WorldSession(NationalRoutes.Create());var root=Path.Combine(Path.GetTempPath(),"travel-old-"+Guid.NewGuid().ToString("N"));new GenerationSaveStore(root,NationalRoutes.Create().Definitions).Save(s,"test",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,TravelWorld.Create().Definitions).Prepare("test"));}
 [Fact] public void HistoricalPeopleUseSourcedHomeSeedsAndLocalVisibility(){var w=TravelWorld.Create();Assert.Equal(3,TravelWorld.People.Length);foreach(var p in TravelWorld.People){Assert.StartsWith("https://",p.Source);var id=new EntityId("person:"+p.Id);Assert.Equal(RegionalCampaign.Site(p.Home),w.Locations.Single(l=>l.Actor==id).Site);Assert.Equal(BranchRoutes.GraphNodes(w).Single(n=>n.Id==p.Home).Position,RegionalCampaign.ActorPointAt(w,id,0));}var s=new WorldSession(w);Assert.Contains(s.GetNearbyActors(ContractFixture.Officer),n=>n.Actor==new EntityId("person:nobunaga"));Assert.DoesNotContain(s.GetNearbyActors(ContractFixture.Officer),n=>n.Actor==new EntityId("person:shingen"));}
 [Fact] public void MultipleJourneysPreserveEarlierDispatchOrigins(){var s=New();Go(s,"sakai");Arrive(s);var old=s.DiagnosticSnapshot().Couriers!.Missions[0].Origin;Go(s,"sumoto");Arrive(s);Go(s,"castle");Arrive(s);Assert.Equal(old,s.DiagnosticSnapshot().Couriers!.Missions[0].Origin);ContractValidation.Validate(s.DiagnosticSnapshot());Assert.All(s.DiagnosticSnapshot().Couriers!.Missions,c=>Assert.Empty(c.Legs));}
 [Fact] public void HistoricalSourceAndAppearanceAreNotOwnershipOrNpcAi(){var w=TravelWorld.Create();Assert.Empty(w.LandRights);Assert.All(TravelWorld.People,p=>Assert.DoesNotContain(w.Grants,g=>g.Agent==new EntityId("person:"+p.Id)));}
 [Fact] public void CouriersAlsoWaitAndResumeOnScheduledSeaDeparture(){var s=New();Go(s,"sumoto");Arrive(s);Assert.Equal(ResultCode.Accepted,s.InspectRoad(ContractFixture.Officer,"nation-sakai-sumoto",s.Revision).Code);var w=s.DiagnosticSnapshot();var c=w.Couriers!.Missions.Last();var l=c.Legs.First(l=>NationalRoutes.Sea(l.Edge));var dep=TravelWorld.Departure(w,l.Edge,l.StartAt);Assert.True(dep>=l.StartAt+300);Assert.Equal(l.From,RegionalCampaign.Position(w,c,dep-1));Assert.Equal(l.From,RegionalCampaign.Position(w,c,dep));Assert.NotEqual(l.From,RegionalCampaign.Position(w,c,dep+1));s.AdvanceTo(c.ReadyAt);Assert.Contains(s.GetCourierView(ContractFixture.Lord),v=>v.Status=="受領済");}
 [Fact] public void UnknownNationalClosureDoesNotChangePersonalPlan(){var a=TravelWorld.Create();var b=TravelWorld.Create();var id="nation-sakai-sumoto";b.Branches=b.Branches! with{BlockedEdges=[id]};b.Couriers=b.Couriers! with{InitialBlocked=[id]};Assert.Equal(TravelWorld.Move(a,"request:privacy","sumoto").WorkSeconds,TravelWorld.Move(b,"request:privacy","sumoto").WorkSeconds);}
 [Fact] public void TamperedOriginAndPortTimingCannotLoadAsValid(){var s=New();Go(s,"sumoto");var w=s.DiagnosticSnapshot();var j=w.Branches!.Journeys.Single();var ls=j.Legs.ToArray();ls[0]=ls[0] with{From="sakai"};w.Branches=w.Branches with{Journeys=[j with{Legs=ls}]};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));w=s.DiagnosticSnapshot();j=w.Branches!.Journeys.Single();ls=j.Legs.ToArray();var k=Array.FindIndex(ls,l=>NationalRoutes.Sea(l.Edge));ls[k]=ls[k] with{EndAt=ls[k].EndAt-1};w.Branches=w.Branches with{Journeys=[j with{Legs=ls}]};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
 [Theory][InlineData(false)][InlineData(true)] public void SeaCourierRestorePreservesWaitAndArrival(bool departed){var s=New();Go(s,"sumoto");Arrive(s);s.InspectRoad(ContractFixture.Officer,"nation-sakai-sumoto",s.Revision);var c=s.DiagnosticSnapshot().Couriers!.Missions.Last();var l=c.Legs.First(l=>NationalRoutes.Sea(l.Edge));s.AdvanceTo(departed?TravelWorld.Departure(s.DiagnosticSnapshot(),l.Edge,l.StartAt)+10:l.StartAt);var root=Path.Combine(Path.GetTempPath(),"travel-courier-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,TravelWorld.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.25,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetCourierView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetCourierView(ContractFixture.Officer)));s.AdvanceTo(c.ReadyAt);host.Current.SetPaused(false);host.Current.AdvanceTo(c.ReadyAt);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));Assert.Equal(ContractJson.Write(s.GetCourierView(ContractFixture.Lord)),ContractJson.Write(host.Current.GetCourierView(ContractFixture.Lord)));}
}
